-- POST-INSTALLATION READ-ONLY VERIFICATION ONLY. No RPC mutation or business-record changes.
BEGIN ISOLATION LEVEL REPEATABLE READ READ ONLY;
SET LOCAL statement_timeout='20s';
WITH original_catalog AS (-- Read-only production catalog manifest; contains fingerprints, never function bodies or credentials.
SELECT jsonb_build_object(
 'functions',(SELECT jsonb_agg(jsonb_build_object(
  'signature',p.oid::regprocedure::text,'md5',md5(pg_get_functiondef(p.oid)),
  'owner',pg_get_userbyid(p.proowner),'security_definer',p.prosecdef,'volatility',p.provolatile,
  'acl',(SELECT jsonb_agg(jsonb_build_object('grantee',coalesce(r.rolname,'PUBLIC'),'privilege',a.privilege_type,'grantable',a.is_grantable,'grantor',pg_get_userbyid(a.grantor)) ORDER BY coalesce(r.rolname,'PUBLIC'),a.privilege_type,a.is_grantable) FROM aclexplode(coalesce(p.proacl,acldefault('f',p.proowner))) a LEFT JOIN pg_roles r ON r.oid=a.grantee)
 ) ORDER BY n.nspname,p.proname,p.oid::regprocedure::text)
 FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace
 WHERE (n.nspname='public' AND p.proname IN ('admin_approve_renewal','admin_cleanup_yorp_sample_dataset','admin_ensure_renewal_test_account_profile','admin_get_or_create_renewal_test_account','admin_get_yorp_sample_dataset_status','admin_prepare_renewal_test_scenario','admin_reset_renewal_test_scenario','admin_restore_renewal_test_scenario','admin_seed_renewal_test_registration_documents','admin_seed_yorp_sample_dataset','admin_seed_yorp_sample_dataset_core','calculate_organization_renewal_eligibility','delete_organization_account_canonical','diversify_yorp_seed_projects_and_budgets','enforce_accreditation_immutability','enforce_renewal_terminal_immutability','guard_organization_identity_privileges','guard_submitted_registration_document_edits','is_development_or_test_environment','promote_renewal_submission_files_for_review','rebalance_yorp_seed_reporting_quarters','repair_yorp_seeded_fixture_relationships','replace_organization_document_file','update_admin_document_submission_file_review','user_replace_document_submission_file','user_resubmit_renewal','user_start_or_get_renewal_draft','user_submit_renewal','validate_admin_session_token'))
 OR (n.nspname='ytrace_identity' AND p.proname IN ('authorize_reviewer','has_retained_history'))),
 'tables',(SELECT jsonb_agg(jsonb_build_object('schema',n.nspname,'table',c.relname,'owner',pg_get_userbyid(c.relowner),'rls',c.relrowsecurity,'force_rls',c.relforcerowsecurity,
 'acl',(SELECT jsonb_agg(jsonb_build_object('grantee',coalesce(r.rolname,'PUBLIC'),'privilege',a.privilege_type,'grantable',a.is_grantable,'grantor',pg_get_userbyid(a.grantor)) ORDER BY coalesce(r.rolname,'PUBLIC'),a.privilege_type,a.is_grantable) FROM aclexplode(coalesce(c.relacl,acldefault('r',c.relowner))) a LEFT JOIN pg_roles r ON r.oid=a.grantee),
 'columns',(SELECT md5(string_agg(a.attname||':'||format_type(a.atttypid,a.atttypmod)||':'||a.attnotnull||':'||coalesce(pg_get_expr(d.adbin,d.adrelid),''),E'\n' ORDER BY a.attnum)) FROM pg_attribute a LEFT JOIN pg_attrdef d ON d.adrelid=a.attrelid AND d.adnum=a.attnum WHERE a.attrelid=c.oid AND a.attnum>0 AND NOT a.attisdropped),
 'constraints',(SELECT md5(coalesce(string_agg(con.conname||':'||pg_get_constraintdef(con.oid),E'\n' ORDER BY con.conname),'')) FROM pg_constraint con WHERE con.conrelid=c.oid),
 'triggers',(SELECT md5(coalesce(string_agg(t.tgname||':'||t.tgenabled::text||':'||pg_get_triggerdef(t.oid),E'\n' ORDER BY t.tgname),'')) FROM pg_trigger t WHERE t.tgrelid=c.oid AND NOT t.tgisinternal)
 ) ORDER BY n.nspname,c.relname)
 FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace
 WHERE (n.nspname='public' AND c.relname IN ('organization_profiles','organization_accreditations','organization_renewals','document_submissions','document_submission_files','admin_accounts','admin_sessions','roles','budget_requests','liquidation_reports'))
 OR (n.nspname='supabase_migrations' AND c.relname='schema_migrations')),
 'policies',(SELECT md5(coalesce(string_agg(schemaname||':'||tablename||':'||policyname||':'||roles::text||':'||cmd||':'||permissive||':'||coalesce(qual,'')||':'||coalesce(with_check,''),E'\n' ORDER BY schemaname,tablename,policyname),'')) FROM pg_policies WHERE schemaname IN ('public','storage')),
 'roles',(SELECT jsonb_agg(jsonb_build_object('name',r.rolname,'inherit',r.rolinherit,'bypass_rls',r.rolbypassrls,'superuser',r.rolsuper,'memberships',(SELECT coalesce(jsonb_agg(parent.rolname ORDER BY parent.rolname),'[]'::jsonb) FROM pg_auth_members m JOIN pg_roles parent ON parent.oid=m.roleid WHERE m.member=r.oid)) ORDER BY r.rolname) FROM pg_roles r WHERE r.rolname IN ('anon','authenticated','service_role','postgres','authenticator')),
 'migrations',(SELECT jsonb_build_object('count',count(*),'latest',max(version),'fingerprint',md5(coalesce(string_agg(version||':'||coalesce(name,''),E'\n' ORDER BY version),''))) FROM supabase_migrations.schema_migrations)
) AS manifest),
expected_functions(signature,definition_md5,source_md5,owner,security_definer) AS (VALUES
('guard_direct_document_mutation()','7c87d7aab6ad2459b5eebaee7732efbd','78c205203bf617933ba606ffb30ef1db','postgres',false),
('guard_document_parent_mutation()','a5d0f37ccca047e22a9c1207e71600b5','2573890ad54e8bdd2fdfbba358fc04e2','postgres',false),
('replace_organization_document_file(uuid,uuid,timestamp with time zone,text,text,text,bigint)','b8f889a1617b35a3312d7c27a2ee8cde','6a43862235936188e237afc28256274d','postgres',true),
('update_admin_document_submission_file_review(text,uuid,document_submission_status,text)','855c8ad6cc7a9dd621f1921c52e9f18c','6dd339247c5a78c507dca124c0537b2d','postgres',true),
('user_replace_document_submission_file(uuid,text,text,text,numeric,boolean)','25c9ef7e37469b003690ce2787261312','ab31b43878e6121faa84dc9b98afa4f8','postgres',true),
('user_resubmit_renewal(uuid)','925e2cd4a1bc58959cd5520e834bbf3a','4fc55552e211fc4e36ca6891a0546004','postgres',true),
('user_submit_renewal(uuid)','3dd14266cc03c6aa541a4ac81065494b','088980e79e66b27be40f4659635faf59','postgres',true),
('ytrace_document_mutation.guard_file()','b2082c8898b0bdc45caf61490f0d7a7e','c29d26dec63eb2a43529dd5363506eb7','postgres',true),
('ytrace_document_mutation.lock_replacement(uuid)','ae3cfaf97e7ff4985dfde25e9fcf4627','5cab3a4d1efaa8cf259877e3218dcd78','postgres',true)
),
function_results AS (
 SELECT e.signature,p.oid IS NOT NULL AS present,
 md5(pg_get_functiondef(p.oid))=e.definition_md5 AND md5(p.prosrc)=e.source_md5
 AND pg_get_userbyid(p.proowner)=e.owner AND p.prosecdef=e.security_definer AS matches
 FROM expected_functions e LEFT JOIN pg_proc p ON p.oid=to_regprocedure(e.signature)
)
SELECT jsonb_build_object(
 'verified_at',clock_timestamp(),'read_only',current_setting('transaction_read_only'),
 'functions',(SELECT jsonb_agg(to_jsonb(f) ORDER BY signature) FROM function_results f),
 'all_patch_functions_match',(SELECT count(*)=9 AND bool_and(coalesce(matches,false)) FROM function_results),
 'unchanged_catalog_functions_match',(
 SELECT jsonb_agg(f ORDER BY f->>'signature')=$unchanged_functions$[{"acl":[{"grantee":"PUBLIC","grantor":"postgres","grantable":false,"privilege":"EXECUTE"},{"grantee":"anon","grantor":"postgres","grantable":false,"privilege":"EXECUTE"},{"grantee":"authenticated","grantor":"postgres","grantable":false,"privilege":"EXECUTE"},{"grantee":"postgres","grantor":"postgres","grantable":false,"privilege":"EXECUTE"},{"grantee":"service_role","grantor":"postgres","grantable":false,"privilege":"EXECUTE"}],"md5":"33ba7c606820f771e4ed79709bcd188b","owner":"postgres","signature":"admin_approve_renewal(text,uuid,text,text)","volatility":"v","security_definer":true},{"acl":[{"grantee":"postgres","grantor":"postgres","grantable":false,"privilege":"EXECUTE"}],"md5":"804caabb51c48bde392768971a9b6c91","owner":"postgres","signature":"admin_cleanup_yorp_sample_dataset(text,text)","volatility":"v","security_definer":false},{"acl":[{"grantee":"postgres","grantor":"postgres","grantable":false,"privilege":"EXECUTE"}],"md5":"e08abef51274c58a5202440fd5242eb1","owner":"postgres","signature":"admin_ensure_renewal_test_account_profile(text)","volatility":"v","security_definer":false},{"acl":[{"grantee":"postgres","grantor":"postgres","grantable":false,"privilege":"EXECUTE"}],"md5":"1fe788c8e9983ecc49a925e76f1cd6c9","owner":"postgres","signature":"admin_get_or_create_renewal_test_account(text)","volatility":"v","security_definer":false},{"acl":[{"grantee":"anon","grantor":"postgres","grantable":false,"privilege":"EXECUTE"},{"grantee":"authenticated","grantor":"postgres","grantable":false,"privilege":"EXECUTE"},{"grantee":"postgres","grantor":"postgres","grantable":false,"privilege":"EXECUTE"},{"grantee":"service_role","grantor":"postgres","grantable":false,"privilege":"EXECUTE"}],"md5":"4b274df3cba7af260c503260e9fc92f2","owner":"postgres","signature":"admin_get_yorp_sample_dataset_status(text,text)","volatility":"v","security_definer":true},{"acl":[{"grantee":"postgres","grantor":"postgres","grantable":false,"privilege":"EXECUTE"}],"md5":"037a3b0b0844a38619f6ce768cb3372b","owner":"postgres","signature":"admin_prepare_renewal_test_scenario(text,integer,date)","volatility":"v","security_definer":false},{"acl":[{"grantee":"postgres","grantor":"postgres","grantable":false,"privilege":"EXECUTE"}],"md5":"8ce7c63826f845120f0616bf3faa2324","owner":"postgres","signature":"admin_reset_renewal_test_scenario(text)","volatility":"v","security_definer":false},{"acl":[{"grantee":"postgres","grantor":"postgres","grantable":false,"privilege":"EXECUTE"}],"md5":"d83a26a06867d1b2d1f21027d3e4c6f0","owner":"postgres","signature":"admin_restore_renewal_test_scenario(text)","volatility":"v","security_definer":false},{"acl":[{"grantee":"postgres","grantor":"postgres","grantable":false,"privilege":"EXECUTE"}],"md5":"a3e4de38869718a570b7e6b8b2e22d1f","owner":"postgres","signature":"admin_seed_renewal_test_registration_documents(text)","volatility":"v","security_definer":false},{"acl":[{"grantee":"postgres","grantor":"postgres","grantable":false,"privilege":"EXECUTE"}],"md5":"b6e376ab185fbe42cc4cd2da3b14c874","owner":"postgres","signature":"admin_seed_yorp_sample_dataset(text,text)","volatility":"v","security_definer":false},{"acl":[{"grantee":"postgres","grantor":"postgres","grantable":false,"privilege":"EXECUTE"}],"md5":"33ccae7f636011a5e2a3310035fdc0a0","owner":"postgres","signature":"admin_seed_yorp_sample_dataset_core(text,text)","volatility":"v","security_definer":false},{"acl":[{"grantee":"PUBLIC","grantor":"postgres","grantable":false,"privilege":"EXECUTE"},{"grantee":"anon","grantor":"postgres","grantable":false,"privilege":"EXECUTE"},{"grantee":"authenticated","grantor":"postgres","grantable":false,"privilege":"EXECUTE"},{"grantee":"postgres","grantor":"postgres","grantable":false,"privilege":"EXECUTE"},{"grantee":"service_role","grantor":"postgres","grantable":false,"privilege":"EXECUTE"}],"md5":"6c46228859ad6e8163988ecbf2db6877","owner":"postgres","signature":"calculate_organization_renewal_eligibility(uuid)","volatility":"s","security_definer":true},{"acl":[{"grantee":"anon","grantor":"postgres","grantable":false,"privilege":"EXECUTE"},{"grantee":"authenticated","grantor":"postgres","grantable":false,"privilege":"EXECUTE"},{"grantee":"postgres","grantor":"postgres","grantable":false,"privilege":"EXECUTE"},{"grantee":"service_role","grantor":"postgres","grantable":false,"privilege":"EXECUTE"}],"md5":"5c1f0179b9f279eb7a99ff9ee8627c3f","owner":"postgres","signature":"delete_organization_account_canonical(text,uuid)","volatility":"v","security_definer":true},{"acl":[{"grantee":"postgres","grantor":"postgres","grantable":false,"privilege":"EXECUTE"}],"md5":"8e784def2e544f558c0a87cd718204cb","owner":"postgres","signature":"diversify_yorp_seed_projects_and_budgets()","volatility":"v","security_definer":false},{"acl":[{"grantee":"PUBLIC","grantor":"postgres","grantable":false,"privilege":"EXECUTE"},{"grantee":"anon","grantor":"postgres","grantable":false,"privilege":"EXECUTE"},{"grantee":"authenticated","grantor":"postgres","grantable":false,"privilege":"EXECUTE"},{"grantee":"postgres","grantor":"postgres","grantable":false,"privilege":"EXECUTE"},{"grantee":"service_role","grantor":"postgres","grantable":false,"privilege":"EXECUTE"}],"md5":"5ea02f1e637d463c4df2e3c7e333aa4b","owner":"postgres","signature":"enforce_accreditation_immutability()","volatility":"v","security_definer":true},{"acl":[{"grantee":"PUBLIC","grantor":"postgres","grantable":false,"privilege":"EXECUTE"},{"grantee":"anon","grantor":"postgres","grantable":false,"privilege":"EXECUTE"},{"grantee":"authenticated","grantor":"postgres","grantable":false,"privilege":"EXECUTE"},{"grantee":"postgres","grantor":"postgres","grantable":false,"privilege":"EXECUTE"},{"grantee":"service_role","grantor":"postgres","grantable":false,"privilege":"EXECUTE"}],"md5":"bdafdef3fded73e5816c199a5ede36c7","owner":"postgres","signature":"enforce_renewal_terminal_immutability()","volatility":"v","security_definer":true},{"acl":[{"grantee":"postgres","grantor":"postgres","grantable":false,"privilege":"EXECUTE"},{"grantee":"service_role","grantor":"postgres","grantable":false,"privilege":"EXECUTE"}],"md5":"3a0fa47c620efc033eec091090bbee1c","owner":"postgres","signature":"guard_organization_identity_privileges()","volatility":"v","security_definer":false},{"acl":[{"grantee":"postgres","grantor":"postgres","grantable":false,"privilege":"EXECUTE"},{"grantee":"service_role","grantor":"postgres","grantable":false,"privilege":"EXECUTE"}],"md5":"c6265ae36e8db8678de7a4e69691008e","owner":"postgres","signature":"guard_submitted_registration_document_edits()","volatility":"v","security_definer":false},{"acl":[{"grantee":"PUBLIC","grantor":"postgres","grantable":false,"privilege":"EXECUTE"},{"grantee":"anon","grantor":"postgres","grantable":false,"privilege":"EXECUTE"},{"grantee":"authenticated","grantor":"postgres","grantable":false,"privilege":"EXECUTE"},{"grantee":"postgres","grantor":"postgres","grantable":false,"privilege":"EXECUTE"},{"grantee":"service_role","grantor":"postgres","grantable":false,"privilege":"EXECUTE"}],"md5":"683db5c6c05d3012f8b9bb36398f61b9","owner":"postgres","signature":"is_development_or_test_environment()","volatility":"s","security_definer":false},{"acl":[{"grantee":"PUBLIC","grantor":"postgres","grantable":false,"privilege":"EXECUTE"},{"grantee":"anon","grantor":"postgres","grantable":false,"privilege":"EXECUTE"},{"grantee":"authenticated","grantor":"postgres","grantable":false,"privilege":"EXECUTE"},{"grantee":"postgres","grantor":"postgres","grantable":false,"privilege":"EXECUTE"},{"grantee":"service_role","grantor":"postgres","grantable":false,"privilege":"EXECUTE"}],"md5":"b1a1e8a2d5eb9e8ccd66b10b6c652b45","owner":"postgres","signature":"promote_renewal_submission_files_for_review()","volatility":"v","security_definer":true},{"acl":[{"grantee":"postgres","grantor":"postgres","grantable":false,"privilege":"EXECUTE"}],"md5":"e486017358c8e1f9264752f8ef5cdbe9","owner":"postgres","signature":"rebalance_yorp_seed_reporting_quarters()","volatility":"v","security_definer":false},{"acl":[{"grantee":"postgres","grantor":"postgres","grantable":false,"privilege":"EXECUTE"}],"md5":"7121da46bd1bf383ab352d49eda2235a","owner":"postgres","signature":"repair_yorp_seeded_fixture_relationships(uuid,uuid,uuid,jsonb,text)","volatility":"v","security_definer":false},{"acl":[{"grantee":"PUBLIC","grantor":"postgres","grantable":false,"privilege":"EXECUTE"},{"grantee":"anon","grantor":"postgres","grantable":false,"privilege":"EXECUTE"},{"grantee":"authenticated","grantor":"postgres","grantable":false,"privilege":"EXECUTE"},{"grantee":"postgres","grantor":"postgres","grantable":false,"privilege":"EXECUTE"},{"grantee":"service_role","grantor":"postgres","grantable":false,"privilege":"EXECUTE"}],"md5":"52bbac2146c7a9473898fb1b6b8908c8","owner":"postgres","signature":"user_start_or_get_renewal_draft(uuid)","volatility":"v","security_definer":true},{"acl":[{"grantee":"PUBLIC","grantor":"postgres","grantable":false,"privilege":"EXECUTE"},{"grantee":"anon","grantor":"postgres","grantable":false,"privilege":"EXECUTE"},{"grantee":"authenticated","grantor":"postgres","grantable":false,"privilege":"EXECUTE"},{"grantee":"postgres","grantor":"postgres","grantable":false,"privilege":"EXECUTE"},{"grantee":"service_role","grantor":"postgres","grantable":false,"privilege":"EXECUTE"}],"md5":"50d5dcf06885fa593fe5355fc8892d69","owner":"postgres","signature":"validate_admin_session_token(text)","volatility":"v","security_definer":true},{"acl":[{"grantee":"postgres","grantor":"postgres","grantable":false,"privilege":"EXECUTE"}],"md5":"0f5766e8fe835c30681dab0ea86571db","owner":"postgres","signature":"ytrace_identity.authorize_reviewer(text)","volatility":"v","security_definer":true},{"acl":[{"grantee":"postgres","grantor":"postgres","grantable":false,"privilege":"EXECUTE"}],"md5":"608aaefe8b604986f752ea289ebed5f5","owner":"postgres","signature":"ytrace_identity.has_retained_history(uuid)","volatility":"s","security_definer":true}]$unchanged_functions$::jsonb
 FROM original_catalog c CROSS JOIN LATERAL jsonb_array_elements(c.manifest->'functions') f
 WHERE f->>'signature' IN ('admin_approve_renewal(text,uuid,text,text)','admin_cleanup_yorp_sample_dataset(text,text)','admin_ensure_renewal_test_account_profile(text)','admin_get_or_create_renewal_test_account(text)','admin_get_yorp_sample_dataset_status(text,text)','admin_prepare_renewal_test_scenario(text,integer,date)','admin_reset_renewal_test_scenario(text)','admin_restore_renewal_test_scenario(text)','admin_seed_renewal_test_registration_documents(text)','admin_seed_yorp_sample_dataset(text,text)','admin_seed_yorp_sample_dataset_core(text,text)','calculate_organization_renewal_eligibility(uuid)','delete_organization_account_canonical(text,uuid)','diversify_yorp_seed_projects_and_budgets()','enforce_accreditation_immutability()','enforce_renewal_terminal_immutability()','guard_organization_identity_privileges()','guard_submitted_registration_document_edits()','is_development_or_test_environment()','promote_renewal_submission_files_for_review()','rebalance_yorp_seed_reporting_quarters()','repair_yorp_seeded_fixture_relationships(uuid,uuid,uuid,jsonb,text)','user_start_or_get_renewal_draft(uuid)','validate_admin_session_token(text)','ytrace_identity.authorize_reviewer(text)','ytrace_identity.has_retained_history(uuid)')
 ),
 'new_triggers_match',(SELECT count(*)=3 AND bool_and(t.tgenabled='O' AND t.tgtype=CASE WHEN t.tgname='a_document_mutation_guard' THEN 23 ELSE 31 END AND t.tgqual IS NULL AND t.tgnargs=0 AND t.tgattr::text='' AND
  (t.tgname='a_document_mutation_guard' AND c.relname='document_submission_files' AND t.tgfoid=to_regprocedure('ytrace_document_mutation.guard_file()')
   OR t.tgname='b_document_direct_guard' AND c.relname='document_submission_files' AND t.tgfoid=to_regprocedure('public.guard_direct_document_mutation()')
   OR t.tgname='a_document_parent_guard' AND c.relname='document_submissions' AND t.tgfoid=to_regprocedure('public.guard_document_parent_mutation()')))
 FROM pg_trigger t JOIN pg_class c ON c.oid=t.tgrelid JOIN pg_namespace n ON n.oid=c.relnamespace
 WHERE n.nspname='public' AND t.tgname IN ('a_document_mutation_guard','b_document_direct_guard','a_document_parent_guard') AND NOT t.tgisinternal),
 'containment_marker_triggers_match',(SELECT count(*)=4 AND bool_and(t.tgenabled='O' AND t.tgtype=23 AND t.tgqual IS NULL AND t.tgnargs=0 AND t.tgattr::text='' AND t.tgfoid=to_regprocedure('ytrace_production_containment.freeze_fixture_markers()') AND c.relname IN ('budget_requests','document_submission_files','document_submissions','liquidation_reports'))
 FROM pg_trigger t JOIN pg_class c ON c.oid=t.tgrelid JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='public' AND t.tgname='a_production_fixture_markers_guard' AND NOT t.tgisinternal),
 'containment_helper_unchanged',(SELECT md5(pg_get_functiondef(p.oid))='3a551ad03eaa7d24ca136cf1cbecaba9' AND pg_get_userbyid(p.proowner)='postgres' AND NOT p.prosecdef AND p.proacl::text='{postgres=X/postgres}' FROM pg_proc p WHERE p.oid=to_regprocedure('ytrace_production_containment.freeze_fixture_markers()')),
 'owner_rpc_grants',(SELECT jsonb_agg(jsonb_build_object('signature',s,'authenticated',has_function_privilege('authenticated',to_regprocedure(s),'EXECUTE'),'anon',has_function_privilege('anon',to_regprocedure(s),'EXECUTE'),'public_execute',EXISTS(SELECT 1 FROM pg_proc p CROSS JOIN LATERAL aclexplode(coalesce(p.proacl,acldefault('f',p.proowner))) a WHERE p.oid=to_regprocedure(s) AND a.grantee=0 AND a.privilege_type='EXECUTE')) ORDER BY s)
 FROM unnest(ARRAY['user_replace_document_submission_file(uuid,text,text,text,numeric,boolean)','replace_organization_document_file(uuid,uuid,timestamp with time zone,text,text,text,bigint)','user_submit_renewal(uuid)','user_resubmit_renewal(uuid)']) s),
 'admin_review_acl_unchanged',(SELECT jsonb_agg(jsonb_build_object('grantee',coalesce(r.rolname,'PUBLIC'),'privilege',a.privilege_type,'grantable',a.is_grantable,'grantor',pg_get_userbyid(a.grantor)) ORDER BY coalesce(r.rolname,'PUBLIC'),a.privilege_type,a.is_grantable)=$review_acl$[{"grantee":"PUBLIC","grantor":"postgres","grantable":false,"privilege":"EXECUTE"},{"grantee":"anon","grantor":"postgres","grantable":false,"privilege":"EXECUTE"},{"grantee":"authenticated","grantor":"postgres","grantable":false,"privilege":"EXECUTE"},{"grantee":"postgres","grantor":"postgres","grantable":false,"privilege":"EXECUTE"},{"grantee":"service_role","grantor":"postgres","grantable":false,"privilege":"EXECUTE"}]$review_acl$::jsonb FROM pg_proc p CROSS JOIN LATERAL aclexplode(coalesce(p.proacl,acldefault('f',p.proowner))) a LEFT JOIN pg_roles r ON r.oid=a.grantee WHERE p.oid=to_regprocedure('public.update_admin_document_submission_file_review(text,uuid,document_submission_status,text)')),
 'new_guard_api_execute',(SELECT jsonb_agg(jsonb_build_object('signature',s,'anon',has_function_privilege('anon',to_regprocedure(s),'EXECUTE'),'authenticated',has_function_privilege('authenticated',to_regprocedure(s),'EXECUTE')) ORDER BY s) FROM unnest(ARRAY['public.guard_direct_document_mutation()','public.guard_document_parent_mutation()','ytrace_document_mutation.guard_file()','ytrace_document_mutation.lock_replacement(uuid)']) s),
 'private_schema_api_access',(SELECT jsonb_agg(jsonb_build_object('role',r,'usage',has_schema_privilege(r,to_regnamespace('ytrace_document_mutation'),'USAGE'),'create',has_schema_privilege(r,to_regnamespace('ytrace_document_mutation'),'CREATE')) ORDER BY r) FROM unnest(ARRAY['anon','authenticated','service_role']) r),
 'storage_policy_hash',(SELECT md5(coalesce(string_agg(schemaname||':'||tablename||':'||policyname||':'||roles::text||':'||cmd||':'||permissive||':'||coalesce(qual,'')||':'||coalesce(with_check,''),E'\n' ORDER BY schemaname,tablename,policyname),'')) FROM pg_policies WHERE schemaname='storage'),
 'migration_history',(SELECT jsonb_build_object('count',count(*),'latest',max(version),'complete_history_md5',md5(coalesce(jsonb_agg(to_jsonb(m) ORDER BY version),'[]'::jsonb)::text)) FROM supabase_migrations.schema_migrations m),
 'table_metadata',(SELECT manifest->'tables' FROM original_catalog)
) AS verification;
COMMIT;
